spec/book.spec.sh.text:
#!/bin/bash
fail=0
t=$(mktemp); printf '# room\tdate\tstart\tend\twho\n' > "$t"
BOOKINGS=$t bash src/book.sh aoi 2026-01-05 09:00 10:30 x >/dev/null || { echo "book failed"; fail=1; }
grep -q '^# room' "$t" && grep -q '^aoi.2026-01-05.09:00.10:30.x$' "$t" || { echo "booking not appended"; fail=1; }
BOOKINGS=$t bash src/book.sh aoi 2026-01-05 10:00 11:00 y >/dev/null 2>&1; [ $? = 1 ] || { echo "overlap should exit 1"; fail=1; }
rm -f "$t"; exit $fail

spec/capacity.spec.sh.text:
#!/bin/bash
fail=0
t=$(mktemp); printf '# h\n' > "$t"
r=$(mktemp); printf '# room\tcapacity\naoi\t4\nsolo\t1\n' > "$r"
b() { BOOKINGS=$t ROOMS=$r bash src/book.sh "$@" >/dev/null 2>&1; }
b aoi 2026-01-05 09:00 10:00 x 4 || { echo "4 people in aoi rejected"; fail=1; }
b aoi 2026-01-05 10:00 11:00 y 5; [ $? = 1 ] || { echo "5 people in aoi should exit 1"; fail=1; }
b aoi 2026-01-05 12:00 13:00 z many; [ $? = 2 ] || { echo "a non-number should exit 2"; fail=1; }
b momiji 2026-01-05 10:00 11:00 z; [ $? = 2 ] || { echo "unknown room should exit 2"; fail=1; }
b solo 2026-01-05 09:00 10:00 w; [ $? = 0 ] || { echo "omitted people should count as 1 and fit solo (capacity 1)"; fail=1; }
b solo 2026-01-05 11:00 12:00 w 2; [ $? = 1 ] || { echo "2 people in solo should exit 1"; fail=1; }
out=$(BOOKINGS=$t ROOMS=$r bash src/book.sh solo 2026-01-05 13:00 14:00 w 2 2>/dev/null)
[ -z "$out" ] || { echo "over capacity should print nothing to stdout"; fail=1; }
rm -f "$t" "$r"; exit $fail

spec/list.spec.sh.text:
#!/bin/bash
fail=0
t=$(mktemp); printf '# room\tdate\tstart\tend\twho\naoi\t2026-01-02\t10:00\t11:00\tx\nkaede\t2026-01-01\t09:00\t10:00\ty\n' > "$t"
[ "$(BOOKINGS=$t bash src/list.sh | head -1)" = '2026-01-01 09:00-10:00 kaede y' ] || { echo "list sorted"; fail=1; }
[ "$(BOOKINGS=$t bash src/list.sh 2026-01-02)" = '2026-01-02 10:00-11:00 aoi x' ] || { echo "list by date"; fail=1; }
rm -f "$t"; exit $fail

