#!/bin/bash
fail=0
t=$(mktemp); printf '# h\n' > "$t"
b() { BOOKINGS=$t bash src/book.sh "$@" >/dev/null 2>&1; }
b aoi 2026-01-05 09:00 10:00 x 4 || { echo "4 people in aoi rejected"; fail=1; }
b aoi 2026-01-05 10:00 11:00 y 5; [ $? = 1 ] || { echo "5 people in aoi should exit 1"; fail=1; }
b aoi 2026-01-05 12:00 13:00 z many; [ $? = 2 ] || { echo "a non-number should exit 2"; fail=1; }
b momiji 2026-01-05 10:00 11:00 z; [ $? = 2 ] || { echo "unknown room should exit 2"; fail=1; }

# over capacity: the message goes to stderr, stdout stays empty
o=$(BOOKINGS=$t bash src/book.sh aoi 2026-01-05 10:00 11:00 y 5 2>/dev/null)
[ -z "$o" ] || { echo "over capacity should print nothing to stdout"; fail=1; }
e=$(BOOKINGS=$t bash src/book.sh aoi 2026-01-05 10:00 11:00 y 5 2>&1 >/dev/null)
case "$e" in *"over capacity: aoi holds 4, asked for 5"*) ;; *) echo "over capacity message should go to stderr"; fail=1 ;; esac

# people omitted counts as 1: a 1-seat room takes a booking without the count, and refuses 2
r=$(mktemp); printf '# room\tcapacity\nsolo\t1\n' > "$r"
ROOMS=$r BOOKINGS=$t bash src/book.sh solo 2026-01-05 09:00 10:00 x >/dev/null 2>&1 || { echo "omitted people should count as 1"; fail=1; }
ROOMS=$r BOOKINGS=$t bash src/book.sh solo 2026-01-05 10:00 11:00 y 2 >/dev/null 2>&1; [ $? = 1 ] || { echo "2 people in a 1-seat room should exit 1"; fail=1; }
rm -f "$r" "$t"; exit $fail

