BOOKINGS=$t ROOMS=$s bash src/book.sh solo 2026-01-05 16:00 17:00 v 2 >/dev/null 2>&1; [ $? = 1 ] || { echo "2 people in a 1-capacity room should exit 1"; fail=1; }
rm -f "$s"
# 定員超過の理由は stderr に出し、stdout には出さない
out=$(BOOKINGS=$t bash src/book.sh aoi 2026-01-05 18:00 19:00 y 5 2>/dev/null); [ -z "$out" ] || { echo "over capacity message should not go to stdout"; fail=1; }
rm -f "$t"; exit $fail

